def retire_superseded_invitations(apps, schema_editor):
    invitations = apps.get_model("core", "CompanyInvitation").objects.using(
        schema_editor.connection.alias
    )
    members = apps.get_model("core", "CompanyMember").objects.using(
        schema_editor.connection.alias
    )
    users = apps.get_model("core", "User").objects.using(schema_editor.connection.alias)
    events = apps.get_model("core", "AuditEvent").objects.using(
        schema_editor.connection.alias
    )
    for invite in invitations.filter(status="pending").iterator():
        company_uid = invite.company_uid
        newer = invitations.filter(
            company_uid=company_uid, email__iexact=invite.email, pk__gt=invite.pk
        )
        recipients = users.filter(email__iexact=invite.email).values("user_uid")
        member = members.filter(
            company_uid=company_uid, user_uid__in=recipients
        ).first()
        if not newer.exists():
            if not member:
                continue
            if member.status == "removed":
                history = events.filter(company_uid=company_uid)
                removal = (
                    history.filter(
                        action="team.member_removed", target_uid=member.user_uid
                    )
                    .order_by("-pk")
                    .first()
                )
                if (
                    removal
                    and history.filter(
                        action="team.invitation_created",
                        target_uid=invite.invitation_uid,
                        pk__gt=removal.pk,
                    ).exists()
                ):
                    continue
        invitations.filter(pk=invite.pk).update(status="cancelled")


